import type { Article, ArticleSection, Chapter, GlossaryTerm, RichText } from '../types';

const subjectId = 'recht';
const updatedAt = Date.UTC(2026, 10, 18);
const revisionDate = Date.UTC(2026, 10, 19);
const id = (suffix: string) => `recht-${suffix}`;
const termLink = (termId: string, text: string): RichText => ({ text, termId });
const term = (key: string, text: string): RichText => termLink(id(`hw-${key}`), text);
const link = (articleId: string, text: string): RichText => ({ text, articleId });
type Paragraph = string | (string | RichText)[];
const section = (key: string, title: string, ...paragraphs: Paragraph[]): ArticleSection => ({
  id: key, title,
  paragraphs: paragraphs.map(paragraph => (typeof paragraph === 'string' ? [paragraph] : paragraph)
    .map(fragment => typeof fragment === 'string' ? { text: fragment } : fragment)),
});
const exercise = (question: string, answer: string): ArticleSection => ({
  ...section('transfer', 'Selbstkontrolle und Transfer', question),
  hint: { title: 'Musterantwort', content: answer },
});
const sources = (...laws: string[]) => section('rechtsstand', 'Rechtsgrundlagen', ...laws, 'Abgleich mit den amtlichen Normtexten am 18. November 2026.');

const currentSources = (...laws: string[]) => section('rechtsstand', 'Rechtsgrundlagen', ...laws, 'Abgleich mit den Normtexten und Fachquellen am 19. November 2026.');

interface Lesson {
  key: string;
  parent?: string;
  added?: boolean;
  number: string;
  title: string;
  intro: string;
  sections: ArticleSection[];
}

